def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass."""

    if not name or not isinstance(name, str):
        raise ValueError("The `name` parameter must be a non-empty string.")

    if not fields or not isinstance(fields, list):
        raise ValueError("The `fields` parameter must be a non-empty list.")

    if not srid_map or not isinstance(srid_map, dict):
        raise ValueError("The `srid_map` parameter must be a non-empty dictionary.")

    # Create a new class that inherits from object
    class Point(object):
        def __init__(self, **kwargs):
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __repr__(self):
            args = ", ".join(f"{key}={getattr(self, key)!r}" for key in fields)
            return f"{name}({args})"

    # Add SRID property to the Point class
    class SRIDPoint(Point):
        def __init__(self, srid, **kwargs):
            super().__init__(**kwargs)
            if srid not in srid_map:
                raise ValueError(f"Invalid SRID: {srid}")
            self.srid = srid

    return SRIDPoint

