    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                cache[k] = v
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                with lock:
                    try:
                        return cache[k]
                    except KeyError:
                        pass  # key not found
                    v = func(*args, **kwargs)
                    cache[k] = v
                return v
        return wrapper
    return decorator

