def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = {}
            self.access_times = {}
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = self._make_key(args, kwargs, typed=self.typed)
                current_time = self.timer()
                if key in self.cache and current_time - self.access_times[key] < self.ttl:
                    return self.cache[key]
                elif len(self.cache) >= self.maxsize:
                    oldest_key = min(self.access_times, key=self.access_times.get)
                    del self.cache[oldest_key]
                    del self.access_times[oldest_key]

                value = func(*args, **kwargs)
                self.cache[key] = value
                self.access_times[key] = current_time
                return value

            def _make_key(args, kwargs, typed):
                if typed:
                    key = (func, args, tuple(kwargs.items()))
                else:
                    key = (func, tuple(args), frozenset(kwargs.items()))
                return key

            wrapper.ttl_cache_clear = self.cache.clear
            return wrapper

    return TTLCache(maxsize, ttl, timer, typed)

