def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""

    if not hasattr(self, '_interface'):
        raise AttributeError("No interface defined")

    interface = self._interface
    method_descriptions = {}

    for attr_name in dir(interface):
        attr = getattr(interface, attr_name)
        if callable(attr):
            if inspect.isbuiltin(attr):
                description = "Builtin method"
            else:
                description = attr.__doc__
            method_descriptions[attr_name] = description

    if not all:
        method_descriptions = {name: desc for name, desc in method_descriptions.items() if desc}

    return method_descriptions

