def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The input 'prior' must be an instance of InventoryValidator")

    if self.inventory_id != prior.inventory_id:
        raise ValueError("Inventory IDs mismatch")

    if self.version > prior.version:
        raise ValueError("Current inventory version is higher than the prior version")

    if self.inventory_state != 'active':
        raise ValueError("Current inventory must be active")

    if prior.inventory_state != 'archived':
        raise ValueError("Prior inventory must be archived")

    if len(self.items) > len(prior.items):
        raise ValueError("Current inventory has more items than the prior version")

    for item_id, item in prior.items.items():
        if item_id not in self.items:
            raise ValueError(f"Item {item_id} is missing in the current inventory")

        current_item = self.items[item_id]
        if current_item['quantity'] < item['quantity']:
            raise ValueError(f"Item {item_id} quantity has decreased in the current inventory")

        if current_item['price'] != item['price']:
            raise ValueError(f"Item {item_id} price has changed in the current inventory")

    print("Prior validation successful")

