def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    if not isinstance(fixity['files'], dict):
        raise ValueError("The 'files' key must be a dictionary")

    allowed_files = set(manifest_files)

    for file_path, file_info in fixity['files'].items():
        if not isinstance(file_info, dict):
            raise ValueError(f"File info for '{file_path}' must be a dictionary")

        if 'hash' not in file_info:
            raise ValueError(f"File info for '{file_path}' must contain a 'hash' key")

        if file_path not in allowed_files:
            raise ValueError(f"File '{file_path}' not listed in manifest")

        allowed_files.remove(file_path)

    if allowed_files:
        raise ValueError(f"Files listed in manifest but not in fixity block: {', '.join(allowed_files)}")

