def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3 and expr[0] == 'AND':
            left, op1, right = expr
            if op1 == 'OR' and left == right:
                return left
            if op1 == 'AND' and left == right:
                return left
        elif isinstance(expr, tuple) and len(expr) == 3 and expr[0] == 'OR':
            left, op1, right = expr
            if op1 == 'OR' and left == right:
                return left
            if op1 == 'AND' and left == right:
                return left
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            left, op1, right = expr
            if op1 == 'AND':
                if isinstance(left, tuple) and left[0] == 'NOT' and left[1] == right:
                    return right
                if isinstance(right, tuple) and right[0] == 'NOT' and right[1] == left:
                    return left
            if op1 == 'OR':
                if isinstance(left, tuple) and left[0] == 'NOT' and left[1] == right:
                    return left
                if isinstance(right, tuple) and right[0] == 'NOT' and right[1] == left:
                    return right
        return expr

    result = []
    for arg in args:
        if isinstance(arg, tuple):
            if arg[0] == 'AND':
                result.append(apply_absorption(arg))
                result.append(apply_negative_absorption(arg))
            elif arg[0] == 'OR':
                result.append(apply_absorption(arg))
                result.append(apply_negative_absorption(arg))
        else:
            result.append(arg)
    return result

