def load_configurations(config_filenames: List[str], overrides: Dict[str, str] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.

    :param config_filenames: List of configuration filenames to load.
    :param overrides: Optional dictionary containing configuration overrides.
    :param resolve_env: Flag indicating whether to resolve environment variables in the configuration.
    :return: A tuple containing the configuration dictionary and a list of logging.LogRecord instances.
    """
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw_config = fd.read()
                config = toml.loads(raw_config)

                if overrides:
                    config.update(overrides)

                if resolve_env:
                    for key, value in config.items():
                        if isinstance(value, str) and value.startswith('${'):
                            env_var = value[2:-1]
                            config[key] = os.getenv(env_var)

                config_dict[filename] = config
        except FileNotFoundError:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=filename,lineno=0,msg='Configuration file not found.', args=(), exc_info=None))
        except toml.TomlDecodeError as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=filename,lineno=0,msg='Error decoding TOML: {}', args=(str(e),), exc_info=None))
        except Exception as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=filename,lineno=0,msg='Error processing configuration file: {}', args=(str(e),), exc_info=None))

    return config_dict, log_records

