def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__
        elif hasattr(base, '__class__'):
            base_type = base.__class__
            if base_type.__name__ == "type":
                return type

    explicitly_set = explicit_mc is not None

    if explicitly_set:
        return explicit_mc

    for base in bases:
        mc = base.__class__
        if mc is not type:
            return mc

    return type

