def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    import re
    import os

    def linkify_url(url):
        return '<a href="{}" target="_blank">{}</a>'.format(url, url)

    def linkify_text(text):
        return '<a href="{}" target="_blank">{}</a>'.format('/search?q=' + text, text)

    url_pattern = re.compile(r'https?://\S+')
    text_pattern = re.compile(r'\b\w+\b')

    def process_match(match):
        if match.group(0).startswith('http'):
            return linkify_url(match.group(0))
        else:
            return linkify_text(match.group(0))

    result = url_pattern.sub(process_match, text)
    result = text_pattern.sub(process_match, result)

    return result

