def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        parts = handle.split("@")
        if len(parts) != 2:
            raise ValueError("Invalid handle format")
        host, user = parts
        url = f"https://{host}/.well-known/webfinger?resource=acct:{user}"
        with urllib2.urlopen(url, timeout=5) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        print(f"Error retrieving webfinger document for handle {handle}: {e}")
        return None

