def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = {}
    for arg, value in cli_args.items():
        if arg in answer_file_args:
            if answer_file_args[arg] != value:
                deprecated_args[arg] = (value, answer_file_args[arg])
            answer_file_args.pop(arg)  # Remove from answer file to avoid duplicates

    for arg, values in deprecated_args.items():
        print(f"Deprecated argument '{arg}': CLI value {values[0]} differs from answer file value {values[1]}")

