    nested_args_flat = {}
    for k, v in nested_args.items():
        if isinstance(v, dict):
            nested_args_flat.update({f'{k}_{subk}': subv for subk, subv in v.items()})
        else:
            nested_args_flat[k] = v

    custom_args_flat = {}
    for k, v in custom_args.items():
        if isinstance(v, dict):
            custom_args_flat.update({f'{k}_{subk}': subv for subk, subv in v.items()})
        else:
            custom_args_flat[k] = v

    return control_args, nested_args_flat, custom_args_flat

